engine.readUserStats:
function readUserStats() {
  try {
    var raw = window.eli.compat.lsGet("eli_user_stats");
    return raw ? JSON.parse(raw) : null;
  } catch (e) { return null; }
}

// Project the stat blob into the canonical sidebar row list.
// Filters out zero-value rows so the sidebar stays tight on fresh installs.
// FROM v2 _renderSidebarStats shape (mirrors v3 kernel hardcoded rows).

engine.buildStatRows:
function buildStatRows(stats) {
  if (!stats || typeof stats !== "object") return [];
  var defs = [
    { icon: "📅", value: stats.totalActiveDays, label: "Days",          key: "totalActiveDays" },
    { icon: "📄", value: stats.docsReviewed,    label: "Docs reviewed", key: "docsReviewed" },
    { icon: "📝", value: stats.draftsCreated,   label: "Drafts built",  key: "draftsCreated" },
    { icon: "🛡️", value: stats.errorsFixed,    label: "Errors fixed",  key: "errorsFixed" },
    { icon: "⚖️", value: stats.risksFound,     label: "Risks found",   key: "risksFound" },
  ];
  return defs.filter(function (r) { return r.value; });
}

// Engine entry — convenience wrapper for caller orchestration.
// Self-contained: kernel's evalBundle wraps each engine fn in
// `new Function(...)` so sibling references (readUserStats,
// buildStatRows) throw "not defined" at call time. Helpers inlined.

engine.analyze:
function analyze(input, providers) {
  // Inline: readUserStats
  var stats = null;
  try {
    var raw = window.eli.compat.lsGet("eli_user_stats");
    stats = raw ? JSON.parse(raw) : null;
  } catch (e) { stats = null; }
  // Inline: buildStatRows
  var rows = [];
  if (stats && typeof stats === "object") {
    var defs = [
      { icon: "📅", value: stats.totalActiveDays, label: "Days",          key: "totalActiveDays" },
      { icon: "📄", value: stats.docsReviewed,    label: "Docs reviewed", key: "docsReviewed" },
      { icon: "📝", value: stats.draftsCreated,   label: "Drafts built",  key: "draftsCreated" },
      { icon: "🛡️", value: stats.errorsFixed,    label: "Errors fixed",  key: "errorsFixed" },
      { icon: "⚖️", value: stats.risksFound,     label: "Risks found",   key: "risksFound" },
    ];
    rows = defs.filter(function (r) { return r.value; });
  }
  return Promise.resolve({
    rows: rows,
    raw: stats,
    overview: rows.length + " active stat" + (rows.length === 1 ? "" : "s"),
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: "v3.0",
      docHash: null,
      timestamp: Date.now(),
    },
  });
}

view._escStats:
function _escStats(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

// Time-of-day + day-of-week aware greeting (FROM v2 line 16821, kernel
// pre-2026-05-11). Lives here now that eli_stats owns the sidebar top
// chrome. Self-contained — bundle isolation means no module-level deps.

view.renderGreeting:
function renderGreeting(opts) {
  var mount = opts && opts.mount;
  var firstName = opts && opts.firstName;
  if (!mount || !firstName) return null;
  var hour = new Date().getHours();
  var day  = new Date().getDay();
  var greeting = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";
  var emoji    = hour < 12 ? "☕" : hour < 18 ? "👋" : "🌙";
  if (day === 0 || day === 6) { greeting = "Happy weekend"; emoji = "🛋️"; }
  else if (day === 1 && hour < 12) { greeting = "Happy Monday"; emoji = "🚀"; }
  else if (day === 5 && hour >= 15) { greeting = "Almost the weekend"; emoji = "🎉"; }
  var div = document.createElement("div");
  div.className = "_eli3_dashboard_greeting";
  var span = document.createElement("span");
  span.className = "_eli3_greet_full";
  span.textContent = greeting + ", " + firstName + " " + emoji;
  div.appendChild(span);
  mount.appendChild(div);
  return div;
}

// Redline detector chip — pulsing red, shown above the stats when the
// document has tracked changes. Click hands off to Review Redlines
// (if installed) or shows a hint toast.
// Combined doc-source box — paper-source badge on top, redlines pill
// below (if any). Single rounded container so both signals read as
// "what we know about this document." Both rows clickable. Either row
// can be absent: zero redlines → no redlines row; no paperDetect → no
// paper row. Box is null when both are absent.

view.renderRedlineBox:
function renderRedlineBox(opts) {
  var mount = opts.mount;
  if (!mount) return null;
  var count = Number(opts.count || 0);
  var onClickRedlines = opts.onClick || function () {};
  var paperDetect = opts.paperDetect || null;
  var onClickPaper = opts.onClickPaper || function () {};
  var onUndoPaper = opts.onUndoPaper || function () {};
  // 2026-05-18 v49: hide the paper row when the doc doesn't look like
  // an agreement (kernel detector sets noPaper:true if "agreement" is
  // absent from the preamble). Prevents the "3RD PARTY PAPER" badge
  // from appearing on empty / non-contract docs.
  // 2026-05-20: detected 3rd-party paper shows no row (Colgate is the
  // dominant case). Clicking COLGATE PAPER sets the override to 3rd party
  // (init.js onClickPaper); the chip is then replaced by a muted 3RD PARTY
  // row whose click undoes it — it only appears after that manual switch.
  var hasPaper = paperDetect && !paperDetect.noPaper;
  var showPaper = hasPaper && !!paperDetect.isColgatePaper;
  var showUndo = hasPaper && !paperDetect.isColgatePaper && !!paperDetect.overridden && !!paperDetect.originalIsColgatePaper;
  if (!count && !showPaper && !showUndo) return null;
  var box = document.createElement("div");
  box.className = "_eli3_sidebar_docbox";
  // Paper-source row — Colgate-only.
  if (showPaper) {
    var sigList = (paperDetect.signals || []).join(", ") || "no signals matched";
    var isManual = !!paperDetect.overridden;
    var paperRow = document.createElement("div");
    paperRow.className = "_eli3_sidebar_paper _eli3_sidebar_paper_colgate";
    paperRow.title = (isManual
      ? "Manual override (this session only): Colgate paper" +
        " (auto-detect said " + (paperDetect.originalIsColgatePaper ? "Colgate paper" : "3rd-party paper") +
        ", score " + (paperDetect.score || 0) + ")"
      : "Auto-detected: Colgate paper" +
        " (confidence: " + (paperDetect.confidence || "none") +
        ", score " + (paperDetect.score || 0) + ")") +
      "\nSignals: " + sigList +
      "\n\nClick if this is actually 3rd-party paper.";
    paperRow.innerHTML =
      '<span class="_eli3_sidebar_paper_icon">🏢</span>' +
      '<span class="_eli3_sidebar_paper_label">COLGATE PAPER</span>';
    paperRow.onclick = onClickPaper;
    box.appendChild(paperRow);
  }
  if (showUndo) {
    var undoRow = document.createElement("div");
    undoRow.className = "_eli3_sidebar_paper _eli3_sidebar_paper_third";
    undoRow.title = "You set this document to 3rd-party paper (Legal Review detected Colgate paper)." +
      "\nIt stays set until you undo it or reopen ELI.\n\nClick to undo.";
    undoRow.innerHTML =
      '<span class="_eli3_sidebar_paper_icon">↩</span>' +
      '<span class="_eli3_sidebar_paper_label">3RD PARTY</span>' +
      '<span class="_eli3_sidebar_paper_undo">UNDO</span>';
    undoRow.onclick = onUndoPaper;
    box.appendChild(undoRow);
  }
  // Redlines row.
  if (count) {
    var rlRow = document.createElement("div");
    rlRow.className = "_eli3_sidebar_redline";
    // The count comes from Legal Review's last run, not a live scan.
    rlRow.title = count + " tracked change" + (count === 1 ? "" : "s") + " in this document" +
      (opts.asOf ? " (found by Legal Review at " + opts.asOf + ")" : "");
    rlRow.innerHTML =
      '<span class="_eli3_sidebar_redline_icon">📝</span>' +
      '<span class="_eli3_sidebar_redline_count">' + count + '</span>' +
      '<span class="_eli3_sidebar_redline_label">redline' + (count === 1 ? "" : "s") + '</span>';
    rlRow.onclick = onClickRedlines;
    box.appendChild(rlRow);
  }
  mount.appendChild(box);
  return box;
}

// Stats panel. v2 had two toggle-able views (base / gamification)
// behind a ▼/▴ arrow. Port that pattern. Each stat lives in its own
// `.v1-stat` box for visual fidelity. Days Used ELI / Docs Reviewed /
// Drafts Built are the default view; Errors Fixed / Risks Found /
// Time Saved live behind the toggle.

view.renderSidebarStats:
function renderSidebarStats(opts) {
  var mount = opts.mount;
  if (!mount) return null;
  var stats = opts.stats || {};
  // Always render the "User Stats" header + at least the default boxes
  // (even when values are 0 — matches v2 line 16910 default-or-0 pattern).
  var totalDays    = Number(stats.totalActiveDays || 0) || 1;
  var docsReviewed = Number(stats.docsReviewed || 0);
  var draftsBuilt  = Number(stats.draftsCreated || 0);
  var errorsFixed  = Number(stats.errorsFixed || 0);
  var risksFound   = Number(stats.risksFound || 0);
  // Canonical field is hoursSaved (in hours, derived as docsReviewed × 0.5
  // by the stats provider). Legacy field name `timeSavedMinutes` is
  // honored as a fallback for any pre-2026-05-12 install that wrote it.
  var timeSavedMin = (Number(stats.hoursSaved) > 0)
    ? Math.round(Number(stats.hoursSaved) * 60)
    : Number(stats.timeSavedMinutes || 0);
  function _fmtTime(mins) {
    if (!mins) return "0m";
    var h = Math.floor(mins / 60);
    var m = mins % 60;
    if (h > 0 && m > 0) return h + "h " + m + "m";
    if (h > 0) return h + "h";
    return m + "m";
  }
  // Persist the toggle state across sidebar repaints (redline count
  // changes, IDB read resolves, etc.) so the user's choice survives
  // visual updates. Stashed on window because the engine fn can't see
  // closure state in this module's caller.
  if (typeof window._eli3_userstats_view !== "string") {
    window._eli3_userstats_view = "base";
  }
  var showingGam = window._eli3_userstats_view === "gam";
  // Click affordance: when onClickHeader is provided, clicking the
  // label OR any stat tile opens the user_stats detail panel. The
  // visual chrome stays identical to before — only cursor:pointer
  // signals interactivity (no chevron, no hover background tint).
  var onClickHeader = opts.onClickHeader;
  var panel = document.createElement("div");
  panel.className = "_eli3_sidebar_userstats";
  panel.innerHTML =
    '<div class="_eli3_sidebar_userstats_hdr"' +
      (onClickHeader ? ' role="button" tabindex="0" title="Open Your Stats" style="cursor:pointer;"' : '') +
    '>User Stats</div>' +
    '<div class="_eli3_sidebar_userstats_base"' + (showingGam ? ' hidden' : '') + '>' +
      '<div class="_eli3_sidebar_userstat">' +
        '<div class="_eli3_sidebar_userstat_num">' + totalDays + '</div>' +
        '<div class="_eli3_sidebar_userstat_lbl">Days Used ELI</div>' +
      '</div>' +
      '<div class="_eli3_sidebar_userstat">' +
        '<div class="_eli3_sidebar_userstat_num">' + docsReviewed + '</div>' +
        '<div class="_eli3_sidebar_userstat_lbl">Docs Reviewed</div>' +
      '</div>' +
      '<div class="_eli3_sidebar_userstat">' +
        '<div class="_eli3_sidebar_userstat_num">' + draftsBuilt + '</div>' +
        '<div class="_eli3_sidebar_userstat_lbl">Drafts Built</div>' +
      '</div>' +
    '</div>' +
    '<div class="_eli3_sidebar_userstats_gam"' + (showingGam ? '' : ' hidden') + '>' +
      '<div class="_eli3_sidebar_userstat">' +
        '<div class="_eli3_sidebar_userstat_num">' + _fmtTime(timeSavedMin) + '</div>' +
        '<div class="_eli3_sidebar_userstat_lbl">Time Saved</div>' +
      '</div>' +
      '<div class="_eli3_sidebar_userstat">' +
        '<div class="_eli3_sidebar_userstat_num">' + errorsFixed + '</div>' +
        '<div class="_eli3_sidebar_userstat_lbl">Errors Fixed</div>' +
      '</div>' +
      '<div class="_eli3_sidebar_userstat">' +
        '<div class="_eli3_sidebar_userstat_num">' + risksFound + '</div>' +
        '<div class="_eli3_sidebar_userstat_lbl">Risks Found</div>' +
      '</div>' +
    '</div>' +
    '<button type="button" class="_eli3_sidebar_userstats_toggle" title="Switch view">' +
      (showingGam ? '▴' : '▾') +
    '</button>';

  // Toggle base ↔ gamification — port of v2 line 16947. Swap which
  // panel has the hidden attribute and flip the arrow glyph. Persist
  // the choice so it survives the next sidebar repaint.
  var toggleBtn = panel.querySelector("._eli3_sidebar_userstats_toggle");
  var baseEl = panel.querySelector("._eli3_sidebar_userstats_base");
  var gamEl  = panel.querySelector("._eli3_sidebar_userstats_gam");
  toggleBtn.onclick = function (ev) {
    ev.stopPropagation();
    var nowShowingGam = !!baseEl.hidden ? false : true;
    // ↑ if base is currently hidden, gam is showing → we want to flip
    //   to base. Otherwise base is showing → flip to gam.
    if (nowShowingGam) {
      baseEl.hidden = true; gamEl.hidden = false; toggleBtn.textContent = "▴";
      window._eli3_userstats_view = "gam";
    } else {
      baseEl.hidden = false; gamEl.hidden = true; toggleBtn.textContent = "▾";
      window._eli3_userstats_view = "base";
    }
  };
  // Wire click on label + every stat tile so any of them opens the
  // detail panel. Each gets cursor:pointer as the only visual signal.
  if (onClickHeader) {
    function _bind(el) {
      if (!el) return;
      el.style.cursor = "pointer";
      el.addEventListener("click", function (ev) {
        ev.stopPropagation();
        try { onClickHeader(); } catch (_e) {}
      });
    }
    var hdrEl = panel.querySelector("._eli3_sidebar_userstats_hdr");
    _bind(hdrEl);
    if (hdrEl) {
      hdrEl.addEventListener("keydown", function (ev) {
        if (ev.key === "Enter" || ev.key === " ") {
          ev.preventDefault();
          try { onClickHeader(); } catch (_e) {}
        }
      });
    }
    var tileEls = panel.querySelectorAll("._eli3_sidebar_userstat");
    for (var ti = 0; ti < tileEls.length; ti++) _bind(tileEls[ti]);
    // NOTE: the base↔gam toggle button (▾/▴) is a sibling of the tiles,
    // not a child — clicks on it never bubble through a bound element,
    // so no stopPropagation guard is needed. An earlier capture-phase
    // listener here swallowed the toggle's own onclick in the Office
    // iframe; removed. Toggle's onclick (set at line ~194) flips views
    // as before.
  }
  mount.appendChild(panel);

  // ─── Your AI Spend (2026-05-28) ──────────────────────────────────────
  // SIDEBAR PANEL HIDDEN 2026-05-28 — the same data lives in the full
  // User Stats detail tool (admin_telemetry_inspector), accessible by
  // clicking the User Stats sidebar label. Keeping the code in place
  // (just gated `if (false)`) so the wiring can be re-enabled with a
  // one-line flip if we want it back.
  if (false && stats.aiSummary && (stats.aiSummary.totalCostUSD > 0 ||
      stats.aiSummary.totalTokens > 0 || stats.aiSummary.totalCalls > 0)) {
    function _fmtMoneyU(v) {
      var n = Number(v) || 0;
      if (n === 0) return "$0";
      if (n < 0.01) return "$" + n.toFixed(4);
      if (n < 1)    return "$" + n.toFixed(3);
      if (n < 100)  return "$" + n.toFixed(2);
      return "$" + Math.round(n).toLocaleString();
    }
    function _fmtNumU(v) {
      var n = Number(v) || 0;
      if (n < 1000) return String(n);
      if (n < 1e6)  return (n / 1e3).toFixed(n < 10000 ? 2 : 1) + "K";
      return (n / 1e6).toFixed(2) + "M";
    }
    function _fmtDateU(iso) {
      if (!iso) return "—";
      var p = String(iso).split("-");
      if (p.length !== 3) return iso;
      var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
      var m = Number(p[1]) - 1;
      var d = Number(p[2]);
      if (m < 0 || m > 11 || !d) return iso;
      return months[m] + " " + d;
    }
    var s = stats.aiSummary;
    var horizon = (s.firstDate && s.lastDate)
      ? (_fmtDateU(s.firstDate) + " → " + _fmtDateU(s.lastDate))
      : "—";
    var aiPanel = document.createElement("div");
    aiPanel.className = "_eli3_sidebar_userstats";
    aiPanel.style.marginTop = "10px";
    aiPanel.innerHTML =
      '<div class="_eli3_sidebar_userstats_hdr"' +
        (onClickHeader ? ' role="button" tabindex="0" title="Open Your Stats" style="cursor:pointer;"' : '') +
      '>Your AI Spend</div>' +
      '<div class="_eli3_sidebar_userstats_base">' +
        '<div class="_eli3_sidebar_userstat">' +
          '<div class="_eli3_sidebar_userstat_num">' + _fmtMoneyU(s.totalCostUSD) + '</div>' +
          '<div class="_eli3_sidebar_userstat_lbl">Total Spend</div>' +
        '</div>' +
        '<div class="_eli3_sidebar_userstat">' +
          '<div class="_eli3_sidebar_userstat_num">' + _fmtNumU(s.totalCalls) + '</div>' +
          '<div class="_eli3_sidebar_userstat_lbl">AI Calls</div>' +
        '</div>' +
        '<div class="_eli3_sidebar_userstat">' +
          '<div class="_eli3_sidebar_userstat_num">' + _fmtMoneyU(s.avgCostPerDayUSD) + '</div>' +
          '<div class="_eli3_sidebar_userstat_lbl">Avg / Day</div>' +
        '</div>' +
      '</div>' +
      '<div style="text-align:center;font:600 9px Inter,sans-serif;color:#c4b5fd;' +
           'letter-spacing:0.05em;margin-top:6px;opacity:0.85;">' +
        _fmtDateU(s.firstDate) + ' → ' + _fmtDateU(s.lastDate) +
        ' · ' + s.dayCount + ' day' + (s.dayCount === 1 ? '' : 's') +
      '</div>';
    mount.appendChild(aiPanel);
    // Same click-to-open wiring as User Stats panel.
    if (onClickHeader) {
      var _aiHdr = aiPanel.querySelector("._eli3_sidebar_userstats_hdr");
      if (_aiHdr) {
        _aiHdr.style.cursor = "pointer";
        _aiHdr.addEventListener("click", function (ev) {
          ev.stopPropagation();
          try { onClickHeader(); } catch (_e) {}
        });
        _aiHdr.addEventListener("keydown", function (ev) {
          if (ev.key === "Enter" || ev.key === " ") {
            ev.preventDefault();
            try { onClickHeader(); } catch (_e) {}
          }
        });
      }
      var _aiTiles = aiPanel.querySelectorAll("._eli3_sidebar_userstat");
      for (var _ai = 0; _ai < _aiTiles.length; _ai++) {
        (function (el) {
          el.style.cursor = "pointer";
          el.addEventListener("click", function (ev) {
            ev.stopPropagation();
            try { onClickHeader(); } catch (_e) {}
          });
        })(_aiTiles[_ai]);
      }
    }
  }

  return panel;
}

// renderStatsDetail — DEPRECATED 2026-05-28. The sidebar click now opens
// the standalone admin_telemetry_inspector tool ("USER STATS") instead
// of a per-tool detail panel. Kept around (unreachable) only to avoid
// rebuilding the bundler's function manifest. Safe to delete next pass.

view.renderStatsDetail:
function renderStatsDetail(opts) {
  var mount = opts && opts.mount;
  if (!mount) return;
  var stats = (opts && opts.stats) || {};
  var onBack = (opts && opts.onBack) || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _money(v) {
    var n = Number(v) || 0;
    if (n === 0) return "$0";
    if (n < 0.01) return "$" + n.toFixed(4);
    if (n < 1)    return "$" + n.toFixed(3);
    if (n < 100)  return "$" + n.toFixed(2);
    return "$" + Math.round(n).toLocaleString();
  }
  function _num(v) {
    var n = Number(v) || 0;
    if (n < 1000) return String(n);
    if (n < 1e6)  return (n / 1e3).toFixed(n < 10000 ? 2 : 1) + "K";
    return (n / 1e6).toFixed(2) + "M";
  }
  function _date(iso) {
    if (!iso) return "—";
    var p = String(iso).split("-");
    if (p.length !== 3) return iso;
    var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    var m = Number(p[1]) - 1, d = Number(p[2]);
    if (m < 0 || m > 11 || !d) return iso;
    return months[m] + " " + d;
  }
  function _fmtTime(mins) {
    if (!mins) return "0m";
    var h = Math.floor(mins / 60), m = mins % 60;
    if (h > 0 && m > 0) return h + "h " + m + "m";
    if (h > 0) return h + "h";
    return m + "m";
  }

  var totalDays    = Number(stats.totalActiveDays || 0) || 1;
  var docsReviewed = Number(stats.docsReviewed || 0);
  var draftsBuilt  = Number(stats.draftsCreated || 0);
  var errorsFixed  = Number(stats.errorsFixed || 0);
  var risksFound   = Number(stats.risksFound || 0);
  var timeSavedMin = (Number(stats.hoursSaved) > 0)
    ? Math.round(Number(stats.hoursSaved) * 60)
    : Number(stats.timeSavedMinutes || 0);
  var ai = stats.aiSummary || null;

  function _tile(num, lbl, accent) {
    var bg = accent === "gold" ? "linear-gradient(135deg,#fdfaf0,#f7f1de)"
           : accent === "navy" ? "linear-gradient(135deg,#f0f4fb,#e0eaf6)"
           : accent === "green" ? "linear-gradient(135deg,#f0f7f2,#dfeee5)"
           : "linear-gradient(135deg,#f5f5f0,#e9e6da)";
    var border = accent === "gold" ? "#e8dfc4"
               : accent === "navy" ? "#c8d6ea"
               : accent === "green" ? "#c0d8c8"
               : "#d4cdb4";
    var lblColor = accent === "gold" ? "#8a6c1a"
                 : accent === "navy" ? "#1d3a8a"
                 : accent === "green" ? "#1f6e3a"
                 : "#52503e";
    return '<div style="background:' + bg + ';border:1px solid ' + border +
           ';border-radius:8px;padding:16px 14px 14px;">' +
             '<div style="font:700 10px/1 Inter,sans-serif;letter-spacing:0.12em;text-transform:uppercase;color:' + lblColor + ';margin-bottom:10px;">' + _esc(lbl) + '</div>' +
             '<div style="font:800 28px/1.1 Georgia,serif;color:#3a3528;">' + _esc(num) + '</div>' +
           '</div>';
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_stats_detail";
  root.style.cssText = "padding:18px 20px;max-width:920px;";
  var html = '';
  html += '<div style="display:flex;align-items:center;gap:10px;margin-bottom:18px;">' +
            '<button type="button" id="_eli3_stats_detail_back" ' +
              'style="background:linear-gradient(180deg,#fafaf8,#e9e6da);border:1px solid #c4bea8;border-radius:6px;padding:6px 12px;cursor:pointer;font:600 12px Inter,sans-serif;color:#3a3528;">' +
              '← Back' +
            '</button>' +
            '<div style="font:800 22px/1.1 Georgia,serif;color:#3a3528;">📊 Your Stats</div>' +
          '</div>';
  // Productivity counters
  html += '<div style="font:700 11px/1 Inter,sans-serif;letter-spacing:0.16em;text-transform:uppercase;color:#6b624a;margin:18px 0 10px;">Productivity</div>';
  html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;">';
  html +=   _tile(totalDays, "Days Used ELI", "slate");
  html +=   _tile(docsReviewed, "Docs Reviewed", "navy");
  html +=   _tile(draftsBuilt, "Drafts Built", "gold");
  html +=   _tile(_fmtTime(timeSavedMin), "Time Saved", "green");
  html +=   _tile(errorsFixed, "Errors Fixed", "navy");
  html +=   _tile(risksFound, "Risks Found", "gold");
  html += '</div>';
  // AI spend section
  if (ai && (ai.totalCostUSD > 0 || ai.totalTokens > 0 || ai.totalCalls > 0)) {
    html += '<div style="font:700 11px/1 Inter,sans-serif;letter-spacing:0.16em;text-transform:uppercase;color:#6b624a;margin:24px 0 10px;">Your AI Spend</div>';
    html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;">';
    html +=   _tile(_money(ai.totalCostUSD), "Total Spend", "gold");
    html +=   _tile(_num(ai.totalCalls), "AI Calls", "navy");
    html +=   _tile(_num(ai.totalTokens), "Tokens", "navy");
    html +=   _tile(_money(ai.avgCostPerDayUSD), "Avg / Day", "green");
    html += '</div>';
    html += '<div style="font:400 12px/1.5 Inter,sans-serif;color:#8a8167;margin-top:10px;text-align:center;">' +
              _esc(_date(ai.firstDate)) + ' → ' + _esc(_date(ai.lastDate)) +
              ' · ' + ai.dayCount + ' day' + (ai.dayCount === 1 ? '' : 's') +
              ' of activity · ' +
              '<span style="opacity:0.7;">Local only — never shared</span>' +
            '</div>';
  } else {
    html += '<div style="font:700 11px/1 Inter,sans-serif;letter-spacing:0.16em;text-transform:uppercase;color:#6b624a;margin:24px 0 10px;">Your AI Spend</div>';
    html += '<div style="background:#f7f6f1;border:1px dashed #c4bea8;border-radius:8px;padding:18px 16px;text-align:center;font:400 13px/1.5 Inter,sans-serif;color:#6b624a;">' +
              'No AI calls recorded yet. Once you start using ELI\'s AI features, your personal spend will appear here.' +
            '</div>';
  }
  root.innerHTML = html;
  mount.appendChild(root);
  var backBtn = root.querySelector("#_eli3_stats_detail_back");
  if (backBtn) backBtn.onclick = function () { try { onBack(); } catch (_e) {} };
}

// Back-compat — old signature `renderSidebarStats({rows: [...]})` used
// internally before the v2-style restyle. Tools that pass rows still
// work; we just discard them now.

jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["eli_stats"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var buildStatRows      = efns.buildStatRows;
  var renderSidebarStats = vfns.renderSidebarStats;
  var renderRedlineBox   = vfns.renderRedlineBox;
  var renderGreeting     = vfns.renderGreeting;
  if (!buildStatRows || !renderSidebarStats) {
    eli.log.event("tool", "eli_stats_load_failed", {
      hasBuild: !!buildStatRows, hasView: !!renderSidebarStats,
    });
    return;
  }

  // ─── [LOAD-TIMES] ───────────────────────────────────────────────
  // Stamp each startup tool as it finishes loading, so About can show when
  // ELI was actually ready. About's "Boot" covers only first paint; the
  // boot and preload tools load AFTER that, each tier in one continuous
  // run. This tool can't see tools that loaded before it (build_draft goes
  // first), so the first few are unstamped — the END of the run, which is
  // the number that matters, is exact. Perf marks only: nothing stored,
  // nothing sent. Stops after a minute — a tool installed mid-session is
  // not startup. About reads these in eli_kit/view.js.
  (function _stampStartupLoads() {
    if (!eli.bus || typeof eli.bus.on !== "function" || !eli.perf || typeof eli.perf.mark !== "function") return;
    var offTool = eli.bus.on("tool:loaded", function (p) {
      if (!p || !p.id || (p.tier !== "boot" && p.tier !== "preload")) return;
      try { eli.perf.mark("tool_loaded:" + p.id); } catch (_) {}
    });
    // Between the tiers the kernel reads IDB; a gap across this mark is
    // that read, not the next tool's cost.
    var offTier = eli.bus.on("tools:loaded", function () {
      try { eli.perf.mark("tools_boot_tier_done"); } catch (_) {}
    });
    setTimeout(function () {
      try { offTool && offTool(); offTier && offTier(); } catch (_) {}
    }, 60000);
  })();

  // ─── Install real eli.stats provider (kernel had only a stub) ────────
  // 2026-05-12 offload: counter logic + IDB-backed flush + dailyTick all
  // moved here from kernel §12. Kernel's stub buffers any record/set
  // calls that fire before this init runs (other boot-tier tools may
  // run before us). We drain the buffer and replay AFTER hydrating from
  // IDB so streak / threshold checks see the real total.
  _installRealStatsProvider(eli);

  function _installRealStatsProvider(eli) {
    var STORE_STATS = "stats";
    var FLUSH_DEBOUNCE_MS = 5000;
    var FLUSH_THRESHOLD = 50;
    // Snapshot the kernel stub's state BEFORE we overwrite.
    var stubBuffer = (eli.stats && typeof eli.stats._drainBuffer === "function")
      ? eli.stats._drainBuffer() : [];
    var stubCacheSnapshot = (eli.stats && typeof eli.stats.getAll === "function")
      ? eli.stats.getAll() : {};

    var _cache = {};     // stat_id → { stat_id, count, lastUpdated }
    var _pending = {};   // changes since last flush
    var _flushTimer = null;
    var _hydrated = false;

    function record(name, count) {
      if (!name) return;
      count = count == null ? 1 : Number(count);
      if (!isFinite(count)) return;
      var existing = _cache[name] || { stat_id: name, count: 0, lastUpdated: 0 };
      existing.count = (existing.count || 0) + count;
      existing.lastUpdated = Date.now();
      _cache[name] = existing;
      _pending[name] = existing;
      _scheduleFlush();
      _fireTrophy(name, existing.count);
      if (name === "docsReviewed") _writeDerived("hoursSaved", existing.count * 0.5);
    }
    function set(name, value) {
      if (!name) return;
      value = Number(value);
      if (!isFinite(value)) return;
      var existing = _cache[name] || { stat_id: name, count: 0, lastUpdated: 0 };
      existing.count = value;
      existing.lastUpdated = Date.now();
      _cache[name] = existing;
      _pending[name] = existing;
      _scheduleFlush();
      _fireTrophy(name, value);
    }
    function _writeDerived(name, value) {
      var existing = _cache[name] || { stat_id: name, count: 0, lastUpdated: 0 };
      existing.count = value;
      existing.lastUpdated = Date.now();
      _cache[name] = existing;
      _pending[name] = existing;
      _scheduleFlush();
      _fireTrophy(name, value);
    }
    function _fireTrophy(name, count) {
      try { eli.bus && eli.bus.emit("stats:recorded", { name: name, count: count }); } catch (_) {}
      if (window.eli && window.eli.trophies && typeof window.eli.trophies.evaluate === "function") {
        try { window.eli.trophies.evaluate("stat:recorded", { name: name, count: count }); }
        catch (e) { /* never break stats */ }
      }
    }
    function _scheduleFlush() {
      if (Object.keys(_pending).length >= FLUSH_THRESHOLD) { flush(); return; }
      if (_flushTimer) return;
      _flushTimer = setTimeout(function () { _flushTimer = null; flush(); }, FLUSH_DEBOUNCE_MS);
    }
    function flush() {
      if (_flushTimer) { clearTimeout(_flushTimer); _flushTimer = null; }
      var rows = Object.keys(_pending).map(function (k) { return _pending[k]; });
      if (!rows.length) return Promise.resolve(0);
      _pending = {};
      return eli.storage.putMany(STORE_STATS, rows).catch(function () { return 0; });
    }
    function get(name) { var v = _cache[name]; return v ? v.count : 0; }
    function getAll() {
      var out = {};
      Object.keys(_cache).forEach(function (k) { out[k] = _cache[k].count; });
      return out;
    }
    function getRecord(name) {
      if (!name) return null;
      var row = _cache[name];
      return row && typeof row === "object" ? row : null;
    }
    function reset(name) {
      if (name == null) {
        _cache = {}; _pending = {};
        return eli.storage.clearStore(STORE_STATS).catch(function () {});
      }
      delete _cache[name]; delete _pending[name];
      return eli.storage.delete(STORE_STATS, name).catch(function () {});
    }
    function hydrate() {
      return eli.storage.getAll(STORE_STATS).then(function (rows) {
        rows.forEach(function (row) {
          if (row && row.stat_id) _cache[row.stat_id] = row;
        });
        var legacy = eli.compat.lsGet("eli_tool_freq");
        if (legacy) {
          try {
            var freq = JSON.parse(legacy);
            Object.keys(freq).forEach(function (k) {
              var legacyCount = Number(freq[k]) || 0;
              var idbCount = (_cache[k] && _cache[k].count) || 0;
              if (legacyCount > idbCount) {
                _cache[k] = { stat_id: k, count: legacyCount, lastUpdated: 0 };
              }
            });
          } catch (e) {}
        }
        _hydrated = true;
        return Object.keys(_cache).length;
      }).catch(function () { _hydrated = true; return 0; });
    }
    // ── Daily tick — handles streak / used-X / day-of-week metrics ──
    function _ymd(d) {
      var m = d.getMonth() + 1, day = d.getDate();
      return d.getFullYear() + "-" + (m < 10 ? "0" + m : m) + "-" + (day < 10 ? "0" + day : day);
    }
    function _isUsHoliday(d) {
      var m = d.getMonth() + 1, day = d.getDate(), dow = d.getDay();
      if (m === 1 && day === 1)   return true;
      if (m === 7 && day === 4)   return true;
      if (m === 12 && day === 25) return true;
      if (m === 11 && day >= 22 && day <= 28 && dow === 4) return true;
      if (m === 5  && day >= 25 && day <= 31 && dow === 1) return true;
      if (m === 9  && day >= 1  && day <= 7  && dow === 1) return true;
      return false;
    }
    function dailyTick(nowArg) {
      var now = nowArg || new Date();
      var todayKey = _ymd(now);
      var ls = eli.compat;
      if (!ls) return;
      var stored = ls.lsGet("eli_last_tick_date");
      if (stored === todayKey) return;
      ls.lsSet("eli_last_tick_date", todayKey);
      record("totalActiveDays");
      var prevStreak = Number(ls.lsGet("eli_streak_value") || 0);
      var streakValue = 1;
      if (stored) {
        var lastTick = new Date(stored + "T00:00:00");
        var diff = Math.round((new Date(todayKey + "T00:00:00") - lastTick) / 86400000);
        streakValue = (diff === 1) ? prevStreak + 1 : 1;
      }
      ls.lsSet("eli_streak_value", String(streakValue));
      set("currentStreak", streakValue);
      var dow = now.getDay();
      function _bumpDow(stat) {
        var lastKey = "eli_lastDoW_" + stat;
        var lastStr = ls.lsGet(lastKey);
        var current = (_cache[stat] && _cache[stat].count) || 0;
        var newVal = 1;
        if (lastStr) {
          var lastDate = new Date(lastStr + "T00:00:00");
          var diff = Math.round((new Date(todayKey + "T00:00:00") - lastDate) / 86400000);
          newVal = (diff === 7) ? current + 1 : 1;
        }
        ls.lsSet(lastKey, todayKey);
        set(stat, newVal);
      }
      if (dow === 1) _bumpDow("consecutiveMondays");
      if (dow === 3) _bumpDow("consecutiveWednesdays");
      if (dow === 5) _bumpDow("consecutiveFridays");
      var dom = now.getDate();
      var lastDayOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
      if (dom === 1) record("usedFirstOfMonth");
      if (dom === lastDayOfMonth) record("usedLastOfMonth");
      if (now.getMonth() === 4 && dom === 4) record("usedMay4th");
      if (_isUsHoliday(now)) record("usedHoliday");
      if (dom === 1) {
        ls.lsSet("eli_first_of_month_" + now.getFullYear() + "_" + now.getMonth(), "1");
      }
      if (dom === lastDayOfMonth) {
        var flagKey = "eli_first_of_month_" + now.getFullYear() + "_" + now.getMonth();
        if (ls.lsGet(flagKey)) {
          record("bookendMonths");
          ls.lsRemove(flagKey);
        }
      }
      try { eli.bus.emit("stats:daily-tick", { now: now, dateKey: todayKey }); } catch (_) {}
    }

    // Install real provider.
    window.eli.stats = {
      record: record, set: set, get: get, getAll: getAll, getRecord: getRecord,
      reset: reset, flush: flush, hydrate: hydrate, dailyTick: dailyTick,
      isHydrated: function () { return _hydrated; },
    };

    // Hydrate from IDB, then drain stub buffer to replay any record/set
    // ops that fired before we installed.
    hydrate().then(function (n) {
      // Replay stub buffer.
      stubBuffer.forEach(function (op) {
        if (op.op === "record") record(op.name, op.count);
        else if (op.op === "set") set(op.name, op.value);
      });
      // The stub's _cache may have had increments not in stubBuffer
      // (e.g., direct cache reads). Merge those that don't already exist.
      // Skipping — stubBuffer is the authoritative log.
      try { dailyTick(); } catch (e) {}
      eli.log.event("stats", "real_provider_installed", {
        hydratedCount: n, replayedOps: stubBuffer.length,
      });
      // Replaces the trophy_gallery open-time reconciler (removed 2026-05-16).
      // The reconciler existed because metric trophies only evaluated on
      // stat increment — a user who had docsReviewed=5 in IDB but no
      // re-evaluation since the trophy catalog landed would stay locked
      // until the next docsReviewed++. Fix at the source: re-fire each
      // hydrated counter so window.eli.trophies.evaluate runs against the
      // current total. Guard with a short delay so trophy_gallery's init
      // (preload tier, may run after eli_stats boot-tier) has time to
      // install its evaluator before we call it.
      // 2026-05-18 v56 (CRITICAL): call trophies.evaluate DIRECTLY here
      // instead of through _fireTrophy. The bug: _fireTrophy emits
      // `stats:recorded` on the bus, which telemetry's _onStatsRecorded
      // subscriber consumes — re-recording every hydrated `appOpened*`
      // stat as a fresh tool launch on EVERY boot. Symptom: user
      // resets local telemetry, reloads, sees review_redlines:1 (or
      // any other tool they'd ever clicked) without touching anything.
      // The IGNORED_TOOLS list in eli_telemetry grew reactively to
      // mask this bug for tool after tool. Fix at the SOURCE: replay
      // is not a new record, so don't broadcast it as one.
      function _reevaluateHydratedMetrics() {
        if (!window.eli || !window.eli.trophies || typeof window.eli.trophies.evaluate !== "function") return;
        Object.keys(_cache).forEach(function (k) {
          try {
            window.eli.trophies.evaluate("stat:recorded", { name: k, count: _cache[k].count });
          } catch (_) { /* never break stats */ }
        });
      }
      if (window.eli && window.eli.trophies && typeof window.eli.trophies.evaluate === "function") {
        _reevaluateHydratedMetrics();
      } else if (eli.bus && typeof eli.bus.on === "function") {
        // Wait for trophy_gallery to register its evaluator. The tool
        // loader emits "tool:loaded" with the tool id after evalBundle +
        // init complete.
        var unsub = eli.bus.on("tool:loaded", function (payload) {
          if (!payload || payload.id !== "trophy_gallery") return;
          try { unsub && unsub(); } catch (_) {}
          _reevaluateHydratedMetrics();
        });
      }
    });
  }

  // ─── Stats source ───────────────────────────────────────────────
  // v2 wrote user stats to IDB store "stats" with stat_id="eli_user_stats"
  // (single row with totalActiveDays, docsReviewed, etc. as properties).
  // v3 reads from the same place for backward compat. localStorage is a
  // last-resort fallback for the rare case where IDB hasn't hydrated.
  var _userStats = null;
  var _statsLoaded = false;
  // One read shared by every caller until it lands. The sidebar redraws on
  // each tool load at startup, and each redraw used to start its own read
  // (~37 at startup — Speed Check, 2026-10-16).
  var _statsLoading = null;
  var _repaintQueued = false;
  function _loadUserStats() {
    if (_statsLoaded) return Promise.resolve(_userStats);
    if (_statsLoading) return _statsLoading;
    if (!eli.storage || typeof eli.storage.get !== "function") {
      _statsLoaded = true;
      return Promise.resolve(null);
    }
    _statsLoading = _readUserStats();
    return _statsLoading;
  }
  function _readUserStats() {
    return eli.storage.get("stats", "eli_user_stats").then(function (row) {
      if (row && typeof row === "object") {
        _userStats = row;
        // IDB confirmed populated → the redundant localStorage mirror is
        // provably safe to drop. trophy_gallery no longer writes it;
        // this clears the stale key from existing installs (one-time —
        // lsRemove on an absent key is a no-op on later boots).
        try { if (eli.compat) eli.compat.lsRemove("eli_user_stats"); } catch (e) {}
      } else {
        // Fallback: try the localStorage compat key (some flows mirror).
        try {
          var raw = eli.compat.lsGet("eli_user_stats");
          if (raw) _userStats = JSON.parse(raw);
        } catch (e) { /* tolerate */ }
      }
      _statsLoaded = true;
      return _userStats;
    }).catch(function () {
      _statsLoaded = true;
      return null;
    });
  }
  // Kick off the read at init so by the time the sidebar paints (a few
  // dozen ms later) the cache is usually warm. If still loading when
  // _build runs, we trigger a refresh once the read resolves.
  _loadUserStats();

  // ─── Personal AI Spend cache (2026-05-28) ──────────────────────────
  // Pulls from eli_telemetry.mySummary (this user's local daily rows).
  // Cached in module scope; refreshed at init + after every AI call
  // (debounced) so the sidebar reflects in-session spend without
  // hammering IDB.
  var _aiSummary = null;
  function _loadAiSummary() {
    try {
      var fn = eli.get && eli.get("telemetry", "mySummary");
      if (typeof fn !== "function") return Promise.resolve(null);
      return Promise.resolve(fn()).then(function (res) {
        _aiSummary = res || null;
        return _aiSummary;
      }).catch(function () { return null; });
    } catch (_e) { return Promise.resolve(null); }
  }
  _loadAiSummary().then(function () {
    try { if (eli.dashboard && eli.dashboard.refreshSidebar) eli.dashboard.refreshSidebar(); }
    catch (_e) {}
  });
  // Refresh after AI calls — debounced so a burst of token events only
  // triggers one re-fetch + repaint. 2-second window catches the typical
  // user flow (click button → 1-2s of streaming → token events) without
  // re-fetching mid-stream.
  var _aiRefreshTimer = null;
  function _scheduleAiRefresh() {
    if (_aiRefreshTimer) clearTimeout(_aiRefreshTimer);
    _aiRefreshTimer = setTimeout(function () {
      _aiRefreshTimer = null;
      _loadAiSummary().then(function () {
        try { if (eli.dashboard && eli.dashboard.refreshSidebar) eli.dashboard.refreshSidebar(); }
        catch (_e) {}
      });
    }, 2000);
  }
  try {
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("ai:tokens_used", _scheduleAiRefresh);
    }
  } catch (_e) {}

  // ─── [DOC-STATE-FROM-LR] ────────────────────────────────────────
  // The sidebar's redline pill and Colgate-paper chip show what Legal
  // Review found the last time it ran. ELI Stats used to work both out
  // itself — at startup, 0.8s after every selection change ("doc:dirty"
  // is Word's selection event, so every click in the document) and, for
  // redlines, every 30s; a zero redline count also triggered a full
  // body.getOoxml() (the whole package: 1.8s of Word on a contract,
  // measured 2026-10-14). Only Legal Review needs either answer, and it
  // computes both when opened, then announces them on
  // "doc:redlines_counted" and "doc:paper_detected". Ask ELI and OARS
  // read tracked changes themselves. Neither is cleared on "doc:dirty":
  // a click can't be told from an edit, so the pill's tooltip says when
  // it was counted instead.
  var _redlineCount = 0;
  var _redlineLoaded = false;
  var _redlineAsOf = null;
  var _paperDetect = null;
  // What Legal Review detected before any override — Undo returns to it.
  var _paperAuto = null;
  // Paper-source override: clicking the sidebar's COLGATE PAPER chip sets
  // window._eliPaperOverride = "thirdparty", which the kernel's detector
  // applies on every read. It lives on the window, so it lasts as long as
  // this document's ELI does (each Word document runs its own taskpane, so
  // it can't leak to another document) and a reload clears it. It used to
  // be cleared on "doc:dirty" too, but that is Word's selection event, so
  // any click in the document silently undid it; the sidebar now offers
  // Undo instead.
  function _readPaperOverride() {
    var v = String(window._eliPaperOverride || "").trim();
    return (v === "colgate" || v === "thirdparty") ? v : null;
  }
  function _writePaperOverride(value) {
    if (value === "colgate" || value === "thirdparty") {
      window._eliPaperOverride = value;
    } else {
      try { delete window._eliPaperOverride; } catch (e) { window._eliPaperOverride = undefined; }
    }
  }
  function _clearPaperOverride() {
    _writePaperOverride("");
  }
  // A detection result as it was before the override — the kernel keeps
  // the detector's verdict in originalIsColgatePaper when it applies one.
  function _autoPaper(p) {
    if (!p || !p.overridden) return p;
    var out = Object.assign({}, p, { isColgatePaper: !!p.originalIsColgatePaper });
    delete out.overridden; delete out.originalIsColgatePaper;
    if (out.confidence === "user-set") delete out.confidence;
    return out;
  }
  // What the sidebar shows: Colgate chip, nothing, or the 3RD PARTY Undo row.
  function _paperView(p) {
    if (!p) return "";
    return p.isColgatePaper ? "colgate" : (p.overridden && p.originalIsColgatePaper ? "undo" : "none");
  }
  function _applyPaperDetect(result) {
    var prevView = _paperView(_paperDetect);
    _paperDetect = result || null;
    if (!result || _paperView(result) !== prevView) {
      try {
        if (eli.dashboard && typeof eli.dashboard.refreshSidebar === "function") {
          eli.dashboard.refreshSidebar();
        }
      } catch (e) { /* tolerate */ }
    }
  }

  // Legal Review's count arrives here (see [DOC-STATE-FROM-LR] above).
  function _applyRedlineCount(n) {
    var changed = n !== _redlineCount || !_redlineLoaded;
    _redlineCount = n;
    _redlineLoaded = true;
    if (changed) {
      // refreshSidebar specifically — refresh() also repaints tiles
      // + activity which is wasted work for a redline-count change.
      try {
        if (eli.dashboard && typeof eli.dashboard.refreshSidebar === "function") {
          eli.dashboard.refreshSidebar();
        } else if (eli.dashboard && typeof eli.dashboard.refresh === "function") {
          eli.dashboard.refresh();
        }
      } catch (e) { /* tolerate */ }
    }
    return n;
  }

  // ─── Sidebar slot builder ───────────────────────────────────────
  // Painted into opts.mount by the kernel. Order: redline chip on top
  // (visually loud — pulses when the doc has tracked changes), then
  // the User Stats panel below. Both v2-style boxes.
  function _build(opts) {
    // Greeting first — moved from kernel 2026-05-11 (sidebar top chrome
    // belongs with the stats slot it sits above).
    if (renderGreeting) {
      var ident = (eli.tools && typeof eli.tools.userIdentity === "function")
        ? eli.tools.userIdentity() : {};
      if (ident && ident.firstName) {
        renderGreeting({ mount: opts.mount, firstName: ident.firstName });
      }
    }
    // Always paint the User Stats panel — even with zero values it
    // shows the "User Stats" header + default boxes (matches v2's
    // `stats.docsReviewed || 0` pattern). The slot is therefore never
    // empty, so the kernel always appends it to the sidebar.
    //
    // 2026-05-16: Combined doc-source box — paper-source on top,
    // redlines indicator below (if any). Single rounded container.
    // Click on paper row TOGGLES between Colgate / 3rd Party (in-place,
    // no navigation). Click on redlines row dispatches to redline_authors
    // / review_redlines.
    // 2026-05-17: override now applied by the kernel helper
    // (eli.host.helpers.detectColgatePaperFromDoc applies the override
    // before returning). _paperDetect IS the effective state.
    if (renderRedlineBox && (_redlineCount > 0 || _paperDetect)) {
      renderRedlineBox({
        mount: opts.mount,
        count: _redlineCount,
        asOf: _redlineAsOf,
        paperDetect: _paperDetect,
        onClickPaper: function () {
          // The chip only renders for Colgate paper (view.js showPaper),
          // so this click always means "this is 3rd-party paper". The
          // chip is replaced by a 3RD PARTY row whose click is Undo.
          // Legal Review applies the override itself the next time it
          // detects (the kernel helper reads it), so nothing re-runs here.
          _paperAuto = _autoPaper(_paperDetect);
          _writePaperOverride("thirdparty");
          if (typeof showToast === "function") {
            showToast("Set to 3rd Party Paper (manual override)", "ok");
          }
          _applyPaperDetect(Object.assign({}, _paperDetect, { isColgatePaper: false, overridden: "thirdparty", originalIsColgatePaper: true }));
        },
        onUndoPaper: function () {
          _clearPaperOverride();
          if (typeof showToast === "function") {
            showToast("Back to the detected paper", "ok");
          }
          _applyPaperDetect(_paperAuto || _autoPaper(_paperDetect));
        },
        onClick: function () {
          var openAuthors = eli.get && eli.get("authors", "open");
          if (typeof openAuthors === "function") {
            try { openAuthors(); return; } catch (e) {}
          }
          var handler = eli.get && eli.get("tile", "app_review_redlines");
          if (typeof handler === "function") {
            try { handler(); return; } catch (e) {}
          }
          if (typeof showToast === "function") {
            showToast(_redlineCount + " tracked change" +
              (_redlineCount === 1 ? "" : "s") +
              " — install Review Redlines to manage them.", "info");
          }
        },
      });
    }
    // Merge: _userStats (v2 blob — has unlockedTrophies + dates) with
    // window.eli.stats.getAll() (live counters keyed by stat_id —
    // docsReviewed, draftsCreated, errorsFixed, hoursSaved, etc.).
    // Pre-fix, the sidebar only saw the blob → counters always showed
    // zero until the blob mirrored them (which nothing currently does).
    var liveCounters = {};
    try {
      if (window.eli && window.eli.stats && typeof window.eli.stats.getAll === "function") {
        liveCounters = window.eli.stats.getAll() || {};
      }
    } catch (_) {}
    var mergedStats = Object.assign({}, _userStats || {}, liveCounters);
    // Attach personal AI-spend summary if available. The view renders a
    // separate "Your AI Spend" panel only when this is populated.
    if (_aiSummary) mergedStats.aiSummary = _aiSummary;
    renderSidebarStats({
      mount: opts.mount,
      stats: mergedStats,
      // Click handler — wired on the label AND every stat tile. Opens
      // the standalone "User Stats" tool (admin_telemetry_inspector).
      // It's demand-tier, so bare eli.dispatch returns undefined when
      // the bundle hasn't been eval'd yet. Must route through
      // eli.tools.ensureLoaded (same path the dashboard tile-click
      // uses) to lazy-load the bundle, then dispatch. If the tool
      // isn't installed at all, surface a toast so the user knows.
      onClickHeader: function () {
        var TOOL_ID = "admin_telemetry_inspector";
        var CHANNEL_KEY = "app_admin_telemetry_inspector";
        function _fire() {
          var handler = eli.get && eli.get("tile", CHANNEL_KEY);
          if (typeof handler === "function") {
            try { handler(); } catch (e) {
              if (typeof showToast === "function") {
                showToast("User Stats failed: " + (e && e.message), "err");
              }
            }
            return true;
          }
          return false;
        }
        try {
          // Fast path — if already loaded + registered, fire immediately.
          if (_fire()) return;
          // Lazy-load path — same as the dashboard tile-click flow.
          if (eli.tools && typeof eli.tools.ensureLoaded === "function") {
            eli.tools.ensureLoaded(TOOL_ID).then(function () {
              if (!_fire() && typeof showToast === "function") {
                showToast("User Stats not installed for this user.", "warn");
              }
            }, function (err) {
              if (typeof showToast === "function") {
                showToast("User Stats load failed: " + (err && err.message), "err");
              }
            });
            return;
          }
          // Last resort — no ensureLoaded in this kernel. Hit dispatch
          // anyway in case the tool is loaded under a different path.
          if (eli.dispatch) eli.dispatch("tile", CHANNEL_KEY);
        } catch (_e) {
          if (typeof showToast === "function") showToast("User Stats unavailable.", "warn");
        }
      },
    });
    // If the IDB read is still pending, schedule ONE sidebar repaint
    // once it resolves so the values flip from zero → real.
    if (!_statsLoaded && !_repaintQueued) {
      _repaintQueued = true;
      _loadUserStats().then(function () {
        _repaintQueued = false;
        try { if (eli.dashboard && eli.dashboard.refreshSidebar) eli.dashboard.refreshSidebar(); }
        catch (e) { /* tolerate */ }
      });
    }
  }

  // Register the sidebar slot. v2 had this inline in the kernel; v3
  // offloads it so the kernel doesn't know about stats at all.
  if (eli.dashboard && typeof eli.dashboard.registerSidebarSlot === "function") {
    eli.dashboard.registerSidebarSlot("eli_stats", _build);
  }


  // Repaint sidebar when stat counters change. Debounced — many tools
  // fire multiple records in close succession (e.g. a scan completion
  // fires docsReviewed + risksFound + risksMitigated in the same tick).
  var _sidebarRepaintTimer = null;
  function _scheduleSidebarRepaint() {
    if (_sidebarRepaintTimer) return;
    _sidebarRepaintTimer = setTimeout(function () {
      _sidebarRepaintTimer = null;
      try { if (eli.dashboard && eli.dashboard.refreshSidebar) eli.dashboard.refreshSidebar(); }
      catch (e) { /* tolerate */ }
    }, 300);
  }

  // Legal Review announces what it found ([DOC-STATE-FROM-LR]). No Word
  // work happens here — not at startup, not on clicks, not on a timer.
  if (eli.bus && typeof eli.bus.on === "function") {
    eli.bus.on("doc:redlines_counted", function (p) {
      if (!p || typeof p.count !== "number") return;
      _redlineAsOf = new Date().toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
      var before = _redlineCount;
      _applyRedlineCount(p.count);
      // Same count, new time: the tooltip still needs the new time.
      if (before === p.count) _scheduleSidebarRepaint();
    });
    eli.bus.on("doc:paper_detected", function (p) {
      // The kernel drops the detector's confidence when it applies an
      // override, so keep the earlier result if it reached the same verdict.
      if (p) _paperAuto = (p.overridden && _paperAuto && !!_paperAuto.isColgatePaper === !!p.originalIsColgatePaper)
        ? _paperAuto : _autoPaper(p);
      _applyPaperDetect(p || null);
    });
    // Trophy gallery emits this on every stat.record/set via the
    // evaluator's bus subscription. Reusing it here so the sidebar
    // sees fresh counts the moment a tool records (no full reload).
    eli.bus.on("stats:recorded", _scheduleSidebarRepaint);
  }

  eli.log.event("tool", "eli_stats_initialized", {});
}

jsonTools.css:
/* eli_stats tool styles — sidebar greeting + User Stats panel + redline.
   v2-style boxes (port of taskpane.css :2403 .v1-stat family).
   Injected as <style data-tool="eli_stats">. */

/* Sidebar greeting — moved from kernel 2026-05-11. Gold serif.
   Uses kernel design tokens (--color-gold-warm / --color-gold-dark)
   so it tracks dark/light theme without duplicating the palette. */
._eli3_sidebar ._eli3_dashboard_greeting {
  font: var(--weight-semibold) 18px/1.2 var(--font-serif);
  color: var(--color-gold-warm);
  padding: 2px 2px var(--space-3) 2px;
  word-break: break-word;
}
body.light-mode ._eli3_sidebar ._eli3_dashboard_greeting {
  color: var(--color-gold-dark);
}

._eli3_sidebar_userstats {
  display: flex;
  flex-direction: column;
  margin-top: 8px;
}
._eli3_sidebar_userstats_hdr {
  font: 700 10px/1 'Inter', sans-serif;
  color: #c4b5fd;
  margin: 12px 0 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
._eli3_sidebar_userstats_base,
._eli3_sidebar_userstats_gam {
  display: flex;
  flex-direction: column;
}
/* The HTML5 `hidden` attribute should imply display:none, but the
   base/gam containers above declare `display: flex` which OVERRIDES
   it (CSS specificity: class wins over hidden's UA stylesheet). So
   the toggle appeared to do nothing — base stayed flex even with
   .hidden set. Re-assert display:none explicitly for both panels. */
._eli3_sidebar_userstats_base[hidden],
._eli3_sidebar_userstats_gam[hidden] { display: none; }
._eli3_sidebar_userstat {
  background: #1c2541;
  padding: 12px;
  margin-bottom: 10px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
  border: 1px solid #3a506b;
}
._eli3_sidebar_userstat_num {
  font: 800 18px/1.1 'Inter', sans-serif;
  color: #e5cc80;
  margin-bottom: 2px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
}
._eli3_sidebar_userstat_lbl {
  font: 700 9px/1 'Inter', sans-serif;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
._eli3_sidebar_userstats_toggle {
  background: transparent;
  border: 0;
  font: 700 22px/1 'Inter', sans-serif;
  color: #94a3b8;
  opacity: 0.8;
  cursor: pointer;
  padding: 2px 0 10px;
  text-align: center;
  user-select: none;
  transition: transform 0.2s, opacity 0.15s;
}
._eli3_sidebar_userstats_toggle:hover { transform: scale(1.2); opacity: 1; }
body.light-mode ._eli3_sidebar_userstats_hdr { color: #6d28d9; }
body.light-mode ._eli3_sidebar_userstat {
  background: #ffffff;
  border-color: #cbd5e1;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
}
body.light-mode ._eli3_sidebar_userstat_num {
  color: #92400e;
  text-shadow: none;
}
body.light-mode ._eli3_sidebar_userstat_lbl { color: #64748b; }

/* Doc-source box — wraps the paper-source row + the redlines row.
   Single rounded container so both signals read as "what we know
   about this doc." Either row can be absent. */
._eli3_sidebar_docbox {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Paper-source row — sits ATOP the redlines row inside the docbox.
   Click → legal_review (override picker lives there). */
._eli3_sidebar_paper {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  cursor: help;
  font: 800 9.5px/1 'Inter', sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  border: 1px solid transparent;
  transition: transform 0.12s, box-shadow 0.15s;
}
._eli3_sidebar_paper:hover {
  transform: translateY(-1px);
}
._eli3_sidebar_paper_icon { font-size: 12px; line-height: 1; }
._eli3_sidebar_paper_label { flex: 1; }
._eli3_sidebar_paper_colgate {
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  color: #c9a227;
  border-color: rgba(201, 162, 39, 0.55);
  box-shadow: inset 0 1px 0 rgba(201, 162, 39, 0.18);
}
._eli3_sidebar_paper_colgate:hover {
  box-shadow: inset 0 1px 0 rgba(201, 162, 39, 0.28), 0 2px 6px rgba(201, 162, 39, 0.25);
}
/* 2026-05-22: light-mode chip is much lighter — cream-ivory gradient
   with navy text + warm gold border. Keeps the premium gold accent
   without the heavy navy slab that read as "too dark" in light mode. */
body.light-mode ._eli3_sidebar_paper_colgate {
  background: linear-gradient(135deg, #fefce8 0%, #fef3c7 100%);
  color: #1e293b;
  border-color: rgba(201, 162, 39, 0.65);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.6);
}
body.light-mode ._eli3_sidebar_paper_colgate:hover {
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7), 0 2px 6px rgba(201, 162, 39, 0.30);
}
/* Shown only after the user switched a Colgate-detected doc to 3rd party:
   muted (dashed, no fill) so it reads as "your setting", click = Undo. */
._eli3_sidebar_paper_third {
  cursor: pointer;
  background: transparent;
  color: #94a3b8;
  border: 1px dashed rgba(201, 162, 39, 0.45);
}
._eli3_sidebar_paper_third:hover { color: #e2e8f0; border-color: rgba(201, 162, 39, 0.75); }
body.light-mode ._eli3_sidebar_paper_third { color: #475569; border-color: rgba(201, 162, 39, 0.6); }
body.light-mode ._eli3_sidebar_paper_third:hover { color: #0f172a; }
._eli3_sidebar_paper_undo { font-size: 8.5px; color: #c9a227; letter-spacing: 0.8px; }

/* Redline detector chip — only renders when the doc has tracked changes.
   Pulses red so it's visually loud; click hands off to Review Redlines. */
._eli3_sidebar_redline {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  background: linear-gradient(135deg, #b91c1c 0%, #7c1d12 100%);
  color: #fff7f0;
  border: 1px solid rgba(255, 247, 240, 0.25);
  cursor: pointer;
  font: 700 10px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  transition: transform 0.12s, box-shadow 0.15s;
  box-shadow: 0 0 0 0 rgba(185, 28, 28, 0.55);
  animation: _eli3_sidebar_redline_pulse 2.6s ease-in-out infinite;
}
/* When the redline row sits below the paper row, drop its top margin
   (the docbox already has the margin-top). Otherwise it gets its own. */
._eli3_sidebar_docbox > ._eli3_sidebar_redline { margin-top: 0; }
._eli3_sidebar_redline:hover {
  transform: translateY(-1px);
  box-shadow: 0 2px 8px rgba(185, 28, 28, 0.45);
}
._eli3_sidebar_redline_icon { font-size: 12px; }
._eli3_sidebar_redline_count {
  font-weight: 900;
  font-size: 14px;
  color: #fff;
}
._eli3_sidebar_redline_label { opacity: 0.92; }
@keyframes _eli3_sidebar_redline_pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(185, 28, 28, 0.50); }
  50%      { box-shadow: 0 0 0 6px rgba(185, 28, 28, 0.00); }
}
